    (implb lk vb vcap lo : Z) (ist : list Z) (j7 : list byte) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' junk,
    ms' = MS (mkR (Z_to_bv 64 P_SCI_DEL1_RET) (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2
                  (Z_to_bv 64 (implb + 24)) (Z_to_bv 64 (implb + 32)) (Z_to_bv 64 vb) (Z_to_bv 64 (8 * vcap)) a2 a3 a4 a5 a6 a7
                  (Z_to_bv 64 1) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (implb + 8, implb + 12); (implb + 80, implb + 88)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -64)
    /\ rw_cells rsegs m' (bv_unsigned sp + -64) [CB 8 junk; C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 implb); C8 (Z_to_bv 64 P_SCS_REL_RET)]
    /\ rw_cells rsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells rsegs m' implb (SpcHdrCells (mkSPC VP_SPCI_IMPL 0 1 1) j7)
    /\ PMutex m' (implb + 32) lk
    /\ rw_cells rsegs m' (implb + 72) [C8 (wz vb); C8 (wz vb); C8 (wz (vb + 8 * vcap))].
