    (F : bvmap 5 word) fc (m : mem) (PC implb lk vb vcap lo : Z) (ist : list Z) (j7 : list byte),
  ro_cells rsegs m PC [C8 (wz implb)] -> (PC + 8 <= lo \/ bv_unsigned sp <= PC) ->
  rw_cells rsegs m implb (SpcHdrCells (mkSPC VP_SPCI_IMPL 1 1 1) j7) ->
  PMutex m (implb + 32) lk ->
  rw_cells rsegs m (implb + 72) [C8 (wz vb); C8 (wz (vb + 8 * zlength ist)); C8 (wz (vb + 8 * vcap))] ->
  0 < implb -> implb mod 16 = 0 -> implb + 96 <= hceil -> (implb + 96 <= 0x10000 \/ 0xb4000 <= implb) ->
  0 < vb -> vb + 8 * vcap <= hceil -> 0 < vcap -> zlength ist <= vcap ->
  XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 64 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (sci_segA_post sp gp tp s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc implb lk vb vcap lo ist j7 ra s0 s1 s2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 PC) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SHCOUNT_DTOR) fc None m (seg_rom rsegs)).
