(* [comment removed for export] *)
Definition sci_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (implb u lk lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 implb) (Z_to_bv 64 96) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 ROPDEL2) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp); (implb, implb + 32)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' implb (SpcHdrCells (mkSPC VP_SPCI_IMPL u 0 0) j7)
    /\ PMutex m' (implb + 32) lk.

Lemma sci_segB : forall (rax : word) sp gp tp t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (ra s0 s1 s2 : word) (F : bvmap 5 word) fc (m : mem) (implb u lk lo : Z) (junk j7 : list byte),
  rw_cells rsegs m (bv_unsigned sp + -64) [CB 8 junk; C8 (Z_to_bv 64 18446744073709551615); C8 (Z_to_bv 64 implb); C8 (Z_to_bv 64 P_SCS_REL_RET)] ->
  rw_cells rsegs m (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells rsegs m implb (SpcHdrCells (mkSPC VP_SPCI_IMPL u 1 1) j7) -> 0 <= u < 2^31 ->
  PMutex m (implb + 32) lk ->
  0 < implb -> implb mod 16 = 0 -> implb + 96 <= hceil -> (implb + 96 <= 0x10000 \/ 0xb4000 <= implb) ->
  XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -64) -> lo + 80 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv rsegs m ->
  evt rsegs (sci_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc implb u lk lo j7 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 (implb + 24)) (Z_to_bv 64 (implb + 32)) a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 1) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SCI_DEL1_RET) fc None m (seg_rom rsegs)).
