(* [comment removed for export] *)

Definition SHCOUNT_DTOR_IMPL_STACK : Z := 64 + RFREE_STACK.

Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

  (* [comment removed for export] *)
  Lemma hh_lb_remove_nodup : forall p LB, List.NoDup (map blk_id LB) -> List.NoDup (map blk_id (hs_lb_remove H p LB)).
  Proof.
    intros p LB. induction LB as [|b LB IH]; intros ND.
    - cbn. destruct (hs_lb_remove H p []) as [|c l] eqn:E; [constructor|].
      exfalso. pose proof (hh_lb_remove_In H HH p [] c) as K. rewrite E in K. exact (K (or_introl eq_refl)).
    - cbn in ND. inversion ND as [|x l NI ND']; subst.
      destruct (bptr_eq_dec (blk_id b) p) as [E|NE].
      + destruct b as [[pb Ab] nb]. cbn in E. subst pb. rewrite (proj1 (hh_lb_remove H HH)) by exact NI. exact ND'.
