  Definition ssvc_seg0_post (ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
      (v implb : Z) (S : svch) (j7 : list byte) (m : mem) : machine_state -> Prop :=
    fun ms' => exists a1 a2 m',
      ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (v + 56)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
               F (Z_to_bv 64 P_SHCOUNT_DTOR) fc None m' (seg_rom rsegs)
      /\ munch [(v, v + 8)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
      /\ rw_cells rsegs m' v (SvcHdrCells S ++ [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)] ++ CookieCells j7).

  Lemma ssvc_seg0 : forall ra sp gp tp t0 t1 t2 s0 s1 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
      (F : bvmap 5 word) fc (m : mem) (v implb : Z) (S : svch) (j7 : list byte),
    rw_cells rsegs m v (SvcHdrCells S ++ [C8 (wz (implb + O_SPC_STORAGE)); C8 (wz implb)] ++ CookieCells j7) -> sv_vptr S = VP_SSVC ->
    0 < v -> v + NEWSZ_SSVC <= hceil ->
    mem_inv rsegs m ->
    evt rsegs (ssvc_seg0_post ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc v implb S j7 m)
      (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 v) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
          F (Z_to_bv 64 P_SSVC_DTOR) fc None m (seg_rom rsegs)).
