  Definition ssvc_dtor_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (v implb vb vcap lo B : Z) (S : svch) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pi q : bptr),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (pi, implb, SZ_SPCI_IMPL) LB /\ In (q, vb, 8 * vcap) LB
      /\ hs_RHEAP H s' (hs_lb_remove H pi (hs_lb_remove H q LB)) m'
      /\ StreamSvc (hs_lb_remove H pi (hs_lb_remove H q LB)) m' v S implb
      /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(v, v + 8); (implb, implb + 96); (vb, vb + 8 * vcap)] m m'.

  Definition ssvc_dtor_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (v implb lk vb vcap lo B : Z) (S : svch) (ist : list Z) (errv : word),
      a0 = Z_to_bv 64 v ->
      StreamSvc LB m v S implb ->
      ImplBlock LB m implb (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) lk vb ist vcap) -> 0 < vcap ->
      (vb + 8 * vcap <= implb \/ implb + SZ_SPCI_IMPL <= vb) ->
      XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - SHCOUNT_DTOR_IMPL_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (ssvc_dtor_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB v implb vb vcap lo B S errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_SSVC_DTOR) fc None m (seg_rom rsegs)) mo).

