  Definition DOBJ_SSVC_STACK : Z := 32 + SHCOUNT_DTOR_IMPL_STACK.

  Definition dealloc_obj_ssvc_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (v implb allocb vb lo B : Z) (errv : word) (m : mem) (mo : Model) : config -> Prop :=
    fun cf => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (pv pi q : bptr),
      cfg_ms cf = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                     F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model cf) /\ hs_MPRES H mo (cfg_model cf)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (errno_addr tp) [C4 errv] /\ hs_rauxv_ok H m' B
      /\ In (pv, v, NEWSZ_SSVC) LB /\ In (pi, implb, SZ_SPCI_IMPL) LB /\ In (q, vb, 8) LB
      /\ hs_RHEAP H s' (hs_lb_remove H pv (hs_lb_remove H pi (hs_lb_remove H q LB))) m'
      /\ AllocImpl (hs_lb_remove H pv (hs_lb_remove H pi (hs_lb_remove H q LB))) m' allocb /\ XStatics m'
      /\ xpres LB (bv_unsigned sp) [(v, v + NEWSZ_SSVC); (implb, implb + SZ_SPCI_IMPL); (vb, vb + 8)] m m'.

  Definition dealloc_obj_ssvc_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (AT v implb allocb vb lo B : Z) (S : svch) (ist : list Z) (errv : word),
      a0 = Z_to_bv 64 AT -> a1 = Z_to_bv 64 v ->
      ro_cells rsegs m AT [C8 (wz allocb)] -> (AT + 8 <= lo \/ bv_unsigned sp <= AT) ->
      StreamSvc LB m v S implb -> ImplBlock LB m implb (mkIMPL (mkSPC VP_SPCI_IMPL 1 1 1) 0 vb ist 1) ->   (* [comment removed for export] *)
      AllocImpl LB m allocb -> XStatics m ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - DOBJ_SSVC_STACK ->
      rw_cells rsegs m (errno_addr tp) [C4 errv] -> mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      hs_SR H (dealloc_obj_ssvc_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB v implb allocb vb lo B errv m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_DEALLOC_OBJ_SSVC) fc None m (seg_rom rsegs)) mo).

